using FloorballTraining.CoreBusiness;
using FloorballTraining.CoreBusiness.Dtos;
using Riok.Mapperly.Abstractions;
using AgeGroup = FloorballTraining.CoreBusiness.AgeGroup;

namespace FloorballTraining.UseCases.Helpers;

/// <summary>
/// Entity → DTO mapping (replaces AutoMapper; compile-time generated by Mapperly, no reflection).
/// Same semantics as the former profile: object graphs have cycles (Team ↔ Member ↔ Club, Activity ↔ ActivityTag),
/// so reference handling is on, and DTO members without a source are simply left alone
/// (<see cref="RequiredMappingStrategy.None"/>) because many DTO fields are filled by services afterwards.
/// </summary>
[Mapper(UseReferenceHandling = true, RequiredMappingStrategy = RequiredMappingStrategy.None)]
public partial class AppMapper
{
    // ── Lookups ──────────────────────────────────────────────────────────────────────────────
    [MapProperty(nameof(Tag.ParentTag), nameof(TagDto.ParentTagName), Use = nameof(ParentTagName))]
    public partial TagDto? ToTagDto(Tag? source);
    public partial IReadOnlyList<TagDto> ToTagDtos(IEnumerable<Tag> source);

    // Former AutoMapper rule: a tag without parent has an empty (not null) parent name.
    private static string ParentTagName(Tag? parent) => parent?.Name ?? "";

    public partial PlaceDto? ToPlaceDto(Place? source);
    public partial IReadOnlyList<PlaceDto> ToPlaceDtos(IEnumerable<Place> source);

    public partial EquipmentDto? ToEquipmentDto(Equipment? source);
    public partial IReadOnlyList<EquipmentDto> ToEquipmentDtos(IEnumerable<Equipment> source);

    public partial AgeGroupDto? ToAgeGroupDto(AgeGroup? source);
    public partial IReadOnlyList<AgeGroupDto> ToAgeGroupDtos(IEnumerable<AgeGroup> source);

    [MapProperty("SkillCategory.Name", nameof(SkillDto.SkillCategoryName))]
    private partial SkillDto ToSkillDto(Skill source);

    // ── Activities ───────────────────────────────────────────────────────────────────────────
    public partial ActivityBaseDto? ToActivityBaseDto(Activity? source);
    public partial IReadOnlyList<ActivityBaseDto> ToActivityBaseDtos(IEnumerable<Activity> source);

    public partial ActivityNameAndDescriptionDto? ToActivityNameAndDescriptionDto(Activity? source);
    public partial IReadOnlyList<ActivityNameAndDescriptionDto> ToActivityNameAndDescriptionDtos(IEnumerable<Activity> source);

    public partial ActivityDto? ToActivityDto(Activity? source);
    public partial IReadOnlyList<ActivityDto> ToActivityDtos(IEnumerable<Activity> source);

    [MapProperty("Skill.Name", nameof(ActivitySkillDto.SkillName))]
    [MapProperty("Skill.SkillCategoryId", nameof(ActivitySkillDto.SkillCategoryId))]
    [MapProperty("Skill.SkillCategory.Name", nameof(ActivitySkillDto.SkillCategoryName))]
    private partial ActivitySkillDto ToActivitySkillDto(ActivitySkill source);

    // ── Trainings ────────────────────────────────────────────────────────────────────────────
    // Age groups are exposed as plain AgeGroupDto (the TrainingAgeGroup join row is unwrapped).
    [MapProperty(nameof(Training.TrainingAgeGroups), nameof(TrainingDto.TrainingAgeGroups), Use = nameof(UnwrapAgeGroups))]
    public partial TrainingDto? ToTrainingDto(Training? source);
    public partial IReadOnlyList<TrainingDto> ToTrainingDtos(IEnumerable<Training> source);

    private List<AgeGroupDto> UnwrapAgeGroups(List<TrainingAgeGroup> source) =>
        source.Select(t => ToAgeGroupDto(t.AgeGroup)).OfType<AgeGroupDto>().ToList();

    // ── Clubs / teams / members ──────────────────────────────────────────────────────────────
    public partial ClubDto? ToClubDto(Club? source);
    public partial IReadOnlyList<ClubDto> ToClubDtos(IEnumerable<Club> source);

    [MapperIgnoreTarget(nameof(MemberDto.MemberTeamMembers))]
    public partial MemberDto? ToMemberDto(Member? source);
    public partial IReadOnlyList<MemberDto> ToMemberDtos(IEnumerable<Member> source);

    public partial TeamDto? ToTeamDto(Team? source);
    public partial IReadOnlyList<TeamDto> ToTeamDtos(IEnumerable<Team> source);

    [MapperIgnoreTarget(nameof(TeamMemberDto.Team))]
    public partial TeamMemberDto? ToTeamMemberDto(TeamMember? source);
    public partial IReadOnlyList<TeamMemberDto> ToTeamMemberDtos(IEnumerable<TeamMember> source);

    // ── Appointments / seasons ───────────────────────────────────────────────────────────────
    [MapProperty(nameof(Appointment.Training), nameof(AppointmentDto.TrainingTargets), Use = nameof(TrainingTargets))]
    [MapperIgnoreTarget(nameof(AppointmentDto.Tests))]
    [MapperIgnoreTarget(nameof(AppointmentDto.TestDefinitionIds))]
    public partial AppointmentDto? ToAppointmentDto(Appointment? source);
    public partial IReadOnlyList<AppointmentDto> ToAppointmentDtos(IEnumerable<Appointment> source);

    private static string? TrainingTargets(Training? training) => training != null ? $"{training.GetTrainingGoalsNames()}" : null;

    [MapProperty("Club.Name", nameof(SeasonDto.ClubName))]
    public partial SeasonDto? ToSeasonDto(Season? source);
    public partial IReadOnlyList<SeasonDto> ToSeasonDtos(IEnumerable<Season> source);
}
